function countValid($n) {
    if ($n < 5) return 0;
    $count = 0;
    $m = 2;
    while (true) {
        $power = 1 << $m;
        if ($power > $n) break;
        $max_num = ($power << 1) - 1;
        if ($max_num > $n) $max_num = $n;
        $count += ($max_num - $power + 1);
        $m++;
    }
    return $count;
}
